      } catch (error) {
        await terminateAndReapLaunchedWorker();
        throw new Error(`managed host run: worker capability descriptor failed: ${error instanceof Error ? error.message : String(error)}`);
      }
    }
    child.unref();
    return { pid: child.pid };
  } finally {
    closeSync(logFd);
