   249	type ProviderRegistryLockPidState = 'active' | 'stale' | 'unknown';
   250	
   251	export interface ProviderRegistryLockObservationOps {
   252	  inspectPid?: (pid: number) => ProviderRegistryLockPidState;
   253	  observeProcessStartTimeMs?: (pid: number) => number | undefined;
   254	}
   255	
   256	function inspectProviderRegistryLockPid(pid: number): ProviderRegistryLockPidState {
   257	  try {
   258	    process.kill(pid, 0);
   259	    return 'active';
   260	  } catch (error) {
   261	    const code = (error as NodeJS.ErrnoException).code;
   262	    if (code === 'ESRCH') return 'stale';
   263	    if (code === 'EPERM') return 'active';
   264	    return 'unknown';
   265	  }
   266	}
