   268	/**
   269	 * Best-effort foreign-PID start identity, using ps elapsed time rather than a
   270	 * signal or a provider launch. An unavailable platform/process observation is
   271	 * deliberately not treated as proof of staleness.
   272	 */
   273	function observeProviderRegistryProcessStartTimeMs(pid: number): number | undefined {
   274	  if (!Number.isInteger(pid) || pid <= 0 || process.platform === 'win32') return undefined;
   275	  try {
   276	    const raw = execFileSync('ps', ['-o', 'etimes=', '-p', String(pid)], {
   277	      encoding: 'utf8',
   278	      timeout: 1_000,
   279	      stdio: ['ignore', 'pipe', 'ignore'],
   280	    }).trim();
   281	    const elapsedSeconds = Number(raw);
   282	    return Number.isFinite(elapsedSeconds) && elapsedSeconds >= 0
   283	      ? Math.floor(Date.now() - elapsedSeconds * 1_000)
   284	      : undefined;
   285	  } catch {
   286	    return undefined;
   287	  }
   288	}
