   290	/**
   291	 * Classify an existing registry lock with PID-reuse protection for every local
   292	 * holder, not only this process. If a persisted start identity cannot be read
   293	 * back safely after the PID was observed live, retain it as active rather than
   294	 * falling through to mkdir-lock's age-based unknown-lock reclamation.
   295	 */
   296	export function classifyProviderRegistryLock(
   297	  snapshot: ExistingMkdirLockSnapshot,
   298	  ops: ProviderRegistryLockObservationOps = {},
   299	): ExistingMkdirLockState {
   300	  const holder = snapshot.holder;
   301	  if (!holder || holder.hostname !== hostname()) return 'unknown';
   302	  if (!Number.isInteger(holder.pid) || holder.pid <= 0) return 'unknown';
   303	  const pidState = (ops.inspectPid ?? inspectProviderRegistryLockPid)(holder.pid);
   304	  if (pidState !== 'active') return pidState;
   305	  if (holder.processStartTimeMs !== undefined) {
   306	    const observedStart = (ops.observeProcessStartTimeMs ?? observeProviderRegistryProcessStartTimeMs)(holder.pid);
   307	    // The PID liveness probe succeeded. A missing start-time observation does
   308	    // not demonstrate reuse, so fail closed: generic unknown-lock aging must
   309	    // not reclaim a potentially live provider-registry lock.
   310	    if (observedStart === undefined) return 'active';
   311	    if (!sameProcessStart(holder.processStartTimeMs, observedStart)) return 'stale';
   312	  }
   313	  return 'active';
   314	}
   315	
   316	function withProviderRegistryLock<T>(
   317	  dir: string,
   318	  fn: () => T,
   319	  timing: ProviderRegistryLockTiming = {},
   320	): T {
   321	  const lock = acquireMkdirLock(`${dir}.lock`, {
   322	    label: 'provider-process-registry',
   323	    deadlineMs: timing.deadlineMs ?? 30_000,
   324	    staleMs: timing.staleMs ?? 10_000,
   325	    pollMs: timing.pollMs ?? 10,
   326	    requireHolderToken: true,
   327	    classifyExistingLock: classifyProviderRegistryLock,
   328	    holderInfo: {
   329	      pid: process.pid,
   330	      hostname: hostname(),
   331	      command: 'provider-process-registry mutation',
   332	      acquiredAt: new Date().toISOString(),
   333	      lockId: randomUUID(),
   334	      processStartTimeMs: currentProcessStartTimeMs(),
   335	    },
   336	  });
   337	  try {
   338	    return fn();
   339	  } finally {
   340	    lock.release();
   341	  }
   342	}
   343	
   344	export function scanLiveProviderProcessSlots(
   345	  dir: string,
   346	  now: number,
   347	  staleMs: number,
   348	  lockTiming: ProviderRegistryLockTiming = {},
   349	): ProviderProcessLiveDescriptor[] {
   350	  return withProviderRegistryLock(dir, () => scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs), lockTiming);
   351	}
   352	
   353	export function acquireProviderProcessSlot(
   354	  dir: string,
   355	  cap: number,
   356	  staleMs: number,
   357	  now: number,
   358	  meta: ProviderProcessSlotMeta,
   359	  lockTiming: ProviderRegistryLockTiming = {},
   360	): AcquiredProviderProcessSlot | null {
   361	  mkdirSync(dir, { recursive: true });
   362	  const boundedCap = Number.isFinite(cap) && Number.isInteger(cap) && cap > 0
   363	    ? cap
   364	    : PROVIDER_PROCESS_MAX_CONCURRENT_DEFAULT;
   365	  return withProviderRegistryLock(dir, () => {
   366	    const live = scanLiveProviderProcessSlotsUnlocked(dir, now, staleMs);
   367	    if (live.length >= boundedCap) return null;
   368	    const token = randomUUID();
   369	    const record: ProviderProcessSlotFileMeta = { ...meta, token };
   370	    for (let index = 0; index < boundedCap; index += 1) {
   371	      const file = join(dir, `slot-${index}.json`);
   372	      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
   373	      const judged = readSlotOccupant(file);
   374	      if (!slotReclaimable(judged, file, now, staleMs)) continue;
   375	      if (judged.state !== 'missing') {
   376	        if (!sameSlotOccupant(readSlotOccupant(file), judged)) continue;
   377	        try { unlinkSync(file); } catch { /* exclusive recreate decides the winner */ }
   378	      }
   379	      if (writeProviderProcessSlotExclusive(file, record)) return { file, token };
   380	    }
   381	    return null;
   382	  }, lockTiming);
   383	}
