   385	export function releaseProviderProcessSlot(
   386	  file: string | null,
   387	  token: string | null,
   388	  lockTiming: ProviderRegistryLockTiming = {},
   389	  mutationOps: ProviderRegistryMutationOps = DEFAULT_PROVIDER_REGISTRY_MUTATION_OPS,
   390	): void {
   391	  if (!file || !token) return;
   392	  const dir = dirname(file);
   393	  withProviderRegistryLock(dir, () => {
   394	    const occupant = readSlotOccupant(file);
   395	    if (occupant.state !== 'valid' || occupant.token !== token) return;
   396	    mutationOps.unlink(file);
   397	  }, lockTiming);
   398	}
