   400	/**
   401	 * B-137a F-119: BEST-EFFORT release for `finally` blocks.
   402	 *
   403	 * Two correct-but-opposed requirements meet here:
   404	 *   1. A release failure must be OBSERVABLE, not a silent capacity leak --
   405	 *      releaseProviderProcessSlot therefore throws, and a registry smoke pins
   406	 *      that ("slot unlink mutation failure must be observable instead of
   407	 *      silently leaking capacity").
   408	 *   2. Every production release happens in a bare `finally` (host-run,
   409	 *      autopilot-executor, codex-review-leaf, provider-process-admission), and
   410	 *      a throw from `finally` REPLACES the in-flight exception -- hiding the
   411	 *      real provider failure -- or turns a successful run into a hard error.
   412	 *      host-run.ts's original releaseSlot wrapped its body in try/catch for
   413	 *      exactly this reason; a refactor dropped that.
   414	 *
   415	 * Swallowing inside the primitive would satisfy (2) by destroying (1). So the
   416	 * primitive keeps throwing and `finally` callers use this wrapper, which
   417	 * reports the failure through onFailure instead of hijacking control flow.
   418	 * Capacity is still reclaimable: pid-death detection and the orphan backstop
   419	 * recover a leaked slot, whereas a masked exception is unrecoverable.
   420	 */
   421	export function releaseProviderProcessSlotBestEffort(
   422	  file: string | null,
   423	  token: string | null,
   424	  onFailure: (error: unknown) => void = defaultReleaseFailureReporter,
   425	  lockTiming: ProviderRegistryLockTiming = {},
   426	  mutationOps: ProviderRegistryMutationOps = DEFAULT_PROVIDER_REGISTRY_MUTATION_OPS,
   427	): void {
   428	  try {
   429	    releaseProviderProcessSlot(file, token, lockTiming, mutationOps);
   430	  } catch (error) {
   431	    // Never rethrow: this runs in finally. Reporting must not fail either.
   432	    try {
   433	      onFailure(error);
   434	    } catch { /* a broken reporter must not mask the caller's exception */ }
   435	  }
   436	}
   437	
   438	function defaultReleaseFailureReporter(error: unknown): void {
   439	  const detail = error instanceof Error ? error.message : String(error);
   440	  process.stderr.write(
   441	    `⚠ provider process slot release failed (capacity is reclaimed by pid-death / orphan backstop): ${detail}\n`,
   442	  );
   443	}
