   445	export function transferProviderProcessSlotToProvider(
   446	  file: string | null,
   447	  token: string | null,
   448	  identity: {
   449	    pid: number;
   450	    pgid: number | null;
   451	    spawnedAt: string;
   452	    startFingerprint: string | null;
   453	    processGroupIsolated: boolean;
   454	  },
   455	  lockTiming: ProviderRegistryLockTiming = {},
   456	): boolean {
   457	  if (!file || !token) return false;
   458	  if (
   459	    !Number.isInteger(identity.pid) || identity.pid <= 0
   460	    || !identity.processGroupIsolated
   461	    || !Number.isInteger(identity.pgid) || (identity.pgid ?? 0) <= 0
   462	  ) return false;
   463	  const dir = dirname(file);
   464	  return withProviderRegistryLock(dir, () => {
   465	    const occupant = readSlotOccupant(file);
   466	    if (occupant.state !== 'valid' || occupant.token !== token) return false;
   467	    const next: ProviderProcessSlotFileMeta = {
   468	      ...(occupant.meta as unknown as ProviderProcessSlotFileMeta),
   469	      pid: identity.pid,
   470	      providerPid: identity.pid,
   471	      providerPgid: identity.pgid!,
   472	      providerSpawnedAt: identity.spawnedAt,
   473	      providerStartFingerprint: identity.startFingerprint ?? undefined,
   474	      providerProcessGroupIsolated: true,
   475	      token,
   476	    };
   477	    const temporary = `${file}.${token}.transfer`;
   478	    writeFileSync(temporary, JSON.stringify(next), { encoding: 'utf8', flag: 'wx', mode: 0o600 });
   479	    try {
   480	      // Registry lock + exact token check makes this replacement ownership-safe.
   481	      renameSync(temporary, file);
   482	    } finally {
   483	      try { unlinkSync(temporary); } catch { /* rename already consumed it */ }
   484	    }
   485	    return true;
   486	  }, lockTiming);
   487	}
