   503	/**
   504	 * Conservative source classifier used by the contract smoke. Any production
   505	 * file that imports a provider adapter, is itself an adapter, or combines a
   506	 * child-process API with provider vocabulary must have an explicit inventory
   507	 * row. False positives are classified, never silently excluded, so adding a
   508	 * new direct provider spawn in a new file makes the contract fail closed.
   509	 */
   510	export function isProviderExecutionSurfaceCandidate(relativePath: string, source: string): boolean {
   511	  if (!relativePath.endsWith('.ts')) return false;
   512	  if (/(?:^|\/)(?:tasks|tests|generated)(?:\/|$)/.test(relativePath)) return false;
   513	  if (relativePath === 'core/provider-process-registry.ts') return false;
   514	  if (/^providers\/(?:codex-cli|claude-cli|gemini-cli)\.ts$/.test(relativePath)) return true;
   515	  if (/providers\/(?:codex-cli|claude-cli|gemini-cli)\.js/.test(source)) return true;
   516	  if (/\brunHostRun\s*\(/.test(source)) return true;
   517	  // B-137a: strip documentation filename references before the provider-word
   518	  // scan. The words are matched case-insensitively, so a prose citation of
   519	  // "CLAUDE.md" (the project convention doc, referenced by many core modules)
   520	  // read as a provider reference: any file that both used child_process for git
   521	  // and cited that doc became an "unclassified provider execution surface".
   522	  // scope-contract.ts tripped exactly this way on a comment citing the handler
   523	  // convention -- a docs citation, not a provider workload. Several already
   524	  // inventoried files (audit-scan, audit-trigger, rollout-check,
   525	  // runtime-environment-checks) match for the same non-reason. Stripping only
   526	  // "<provider>.md" filenames keeps every real provider reference intact,
   527	  // including CLAUDE_CLI, claudeCli, 'claude' and providers/claude-cli.js.
   528	  const withoutDocReferences = source.replace(/\b(?:codex|claude|agy|gemini|antigravity)\.md\b/gi, '');
   529	  // B-137a: the provider word no longer requires a trailing \b. The old
   530	  // /\bclaude\b/i missed identifier forms entirely -- `claudeCli`, `CLAUDE_CLI`,
   531	  // `codexRunner` all failed to match, because \b does not break between two
   532	  // word characters or before `_`. A file spawning a provider through such an
   533	  // identifier was therefore invisible to this tripwire (verified against the
