    92	interface HostRunOutputStream {
    93	  write(text: string, callback: (error?: Error | null) => void): boolean;
    94	  on(event: 'error', listener: (error: Error) => void): this;
    95	  removeListener(event: 'error', listener: (error: Error) => void): this;
