   181	function normalizeString(value: unknown): string {
   182	  return typeof value === 'string' ? value.trim() : '';
   183	}
   184	
   185	function optionalPositiveInteger(command: string, field: string, value: unknown): number | undefined {
   186	  if (value === undefined) return undefined;
   187	  if (typeof value !== 'number' || !Number.isFinite(value) || !Number.isInteger(value) || value <= 0) {
   188	    throw new Error(`${command}: --${field} must be a finite positive integer`);
   189	  }
   190	  return value;
   191	}
   192	
   193	function optionalNonnegativeInteger(
   194	  command: string,
   195	  field: string,
   196	  value: unknown,
   197	  maximum?: number,
   198	): number | undefined {
   199	  if (value === undefined) return undefined;
   200	  if (typeof value !== 'number'
   201	    || !Number.isFinite(value)
   202	    || !Number.isInteger(value)
   203	    || value < 0
   204	    || (maximum !== undefined && value > maximum)) {
   205	    const maximumClause = maximum === undefined ? '' : ` <= ${maximum}`;
   206	    throw new Error(`${command}: --${field} must be a finite nonnegative integer${maximumClause}`);
   207	  }
   208	  return value;
   209	}
