   226	/** Format the single stderr usage-summary / refusal line. */
   227	function formatUsageLine(result: HostRunResult): string {
   228	  const u = result.usageSummary;
   229	  if (result.blocked) {
   230	    if (result.refusalReason === 'concurrency_cap_exceeded') {
   231	      const list = (result.liveRuns ?? [])
   232	        .map((r) => `  - pid ${r.pid} ${r.host}${r.storyId ? ` story ${r.storyId}` : ''} agentType ${r.agentType} startedAt ${r.startedAt}`)
   233	        .join('\n');
   234	      return `host_run refused: ${u.reason ?? 'concurrency_cap_exceeded'}${list ? `\n${list}` : ''}`;
   235	    }
   236	    return `host_run refused: ${u.reason ?? result.refusalReason ?? 'blocked'}`;
   237	  }
   238	  if (u.recorded === 'disabled') return 'usage ledger disabled (LATTICE_USAGE_LEDGER=0); no rows recorded';
   239	  if (u.recorded === 'provider-reported') {
   240	    const recordId = u.recordId ? ` (recordId ${u.recordId})` : '';
   241	    return `usage recorded: provider=${u.provider ?? 'unknown'} input=${u.input ?? 'null'} cacheRead=${u.cacheRead ?? 'null'} output=${u.output ?? 'null'}${recordId}`;
   242	  }
   243	  if (u.recorded === 'unavailable') {
   244	    return `usage recorded: unavailable (${u.reason ?? 'no usage surface'})`;
   245	  }
   246	  return `usage: ${u.reason ?? 'not recorded'}`;
   247	}
