   296	export function createHostRunHandlers(ctx: HandlerContext, options: CreateHostRunHandlersOptions = {}) {
   297	  return {
   298	    async host_run(args: HostRunCommandArgs): Promise<HostRunCommandResult | HostRunDetachResult | string> {
   299	      const host = normalizeHost(normalizeString(args.host));
   300	      const agentType = normalizeString(args.agentType);
   301	      if (!agentType) throw new Error('host_run: --agentType is required');
   302	      const timeoutMs = optionalPositiveInteger('host_run', 'timeoutMs', args.timeoutMs);
   303	      const deadlineMs = optionalPositiveInteger('host_run', 'deadlineMs', args.deadlineMs);
   304	      const storyId = normalizeString(args.storyId) || null;
   305	      const reviewRunId = normalizeString(args.reviewRunId) || null;
   306	      const lane = normalizeString(args.lane) || null;
   307	
   308	      // Exactly one of --prompt / --promptFile.
   309	      const hasPrompt = typeof args.prompt === 'string' && args.prompt.length > 0;
   310	      const promptFilePath = normalizeString(args.promptFile);
   311	      const hasPromptFile = promptFilePath.length > 0;
   312	      let promptText: string;
   313	      let formalReviewBinding: {
   314	        headHash: string;
   315	        materialHash: string;
   316	        storyFilesHash: string;
   317	        promptHash: string;
   318	        envelopeId: string | null;
   319	      } | null = null;
   320	      if (args.managedReview === true) {
   321	        if (hasPrompt || hasPromptFile) {
   322	          throw new Error('host_run: --managedReview derives the exact prompt from ReviewRun; do not pass --prompt or --promptFile');
   323	        }
   324	        if (!storyId || !reviewRunId || !lane || agentType !== lane) {
   325	          throw new Error('host_run: --managedReview requires storyId, reviewRunId, lane, and agentType equal to that lane');
   326	        }
   327	        const story = ctx.store.readStory(storyId);
   328	        const reviewRun = assertCurrentReviewRunForEvidence(ctx.store, story, ctx.root, lane, reviewRunId);
   329	        const storyFilesHash = reviewRun.storyFilesHash ?? reviewRun.workspaceBinding?.storyFilesHash ?? '';
   330	        if (!storyFilesHash) throw new Error('host_run: --managedReview requires a ReviewRun with storyFilesHash binding');
   331	        promptText = buildManagedReviewerPrompt(reviewRun.workspaceBinding?.metadataRoot ?? ctx.root, reviewRun);
   332	        formalReviewBinding = {
   333	          headHash: reviewRun.headHash,
   334	          materialHash: reviewRun.materialHash,
   335	          storyFilesHash,
   336	          promptHash: reviewRun.promptHash,
   337	          envelopeId: reviewRun.envelopeId ?? null,
   338	        };
   339	      } else if (hasPrompt === hasPromptFile) {
   340	        throw new Error('host_run: provide exactly one of --prompt or --promptFile (or use --managedReview with an exact ReviewRun)');
   341	      } else if (hasPromptFile) {
   342	        try {
   343	          promptText = readFileSync(promptFilePath, 'utf8');
   344	        } catch (err) {
   345	          throw new Error(`host_run: cannot read --promptFile "${promptFilePath}": ${err instanceof Error ? err.message : String(err)}`);
   346	        }
   347	      } else {
   348	        promptText = args.prompt as string;
   349	      }
   350	      if (promptText.length === 0) {
   351	        throw new Error('host_run: prompt is empty; refuse pre-spawn');
   352	      }
