   442	      // degradation, since passthroughError already records the failure.
   443	      let stdoutBroken = false;
   444	      let stderrBroken = false;
   445	
   446	      // F-020: contain ASYNC stream 'error' events (real EPIPE) for the DURATION of
   447	      // the run. Node terminates the process only when a stream has ZERO 'error'
   448	      // listeners, so simply attaching ours is sufficient containment: we swallow
   449	      // the error and record the first message. Hygiene: exactly our two named
   450	      // listeners are added below and removed with removeListener in the finally
   451	      // — never removeAllListeners, since other code may hold its own listeners on
   452	      // these shared streams. F-024: a write error surfaced through a write CALLBACK
   453	      // folds into the SAME state, so a late EPIPE reported via callback and one
   454	      // reported via the 'error' event are handled identically.
   455	      const recordStreamError = (streamName: 'stdout' | 'stderr') => (err: unknown): void => {
