   464	      const onStderrError = recordStreamError('stderr');
   465	
   466	      // F-024: outstanding-write accounting for the live passthrough AND the final
   467	      // diagnostics, WITHOUT serializing throughput. Every write below is issued as
   468	      // write(text, cb) and is NOT awaited per-chunk; the callback decrements a
   469	      // shared pending counter. drainPending() — awaited by the finally BEFORE the
   470	      // error listeners are removed — resolves once every in-flight write has
   471	      // settled, so a late EPIPE from the FINAL chunk(s) fires while our named
   472	      // 'error' listeners are still attached. This closes the residual window that
   473	      // F-020/F-023 left on fire-and-forget live passthrough writes.
   474	      let pendingWrites = 0;
   475	      const pendingWritesByStream: Record<'stdout' | 'stderr', number> = { stdout: 0, stderr: 0 };
   476	      const releaseLateContainment: Record<'stdout' | 'stderr', (() => void) | null> = { stdout: null, stderr: null };
