   483	        // each still-pending write onto the bounded shared guard before removing
   484	        // this run's listeners; otherwise permanently wedged streams accumulate
   485	        // two listeners per foreground command forever.
   486	        for (const streamName of ['stdout', 'stderr'] as const) {
