   496	        const release = releaseLateContainment[streamName];
   497	        if (!release) return;
   498	        // A real Writable may invoke write(cb) before it emits the matching
   499	        // EPIPE 'error' event on a later next-tick. A promise continuation can
   500	        // run before that next-tick when the write callback settles an async
   501	        // host_run, so retain through the next event-loop turn instead. This
   502	        // still releases promptly for successful writes.
   503	        setImmediate(() => {
