  ]) {
    const signals: Array<{ pgid: number; signal: 'SIGTERM' | 'SIGKILL' }> = [];
    const cleanup = await reapManagedHostRunProviderProcess({
      ...identity,
      spawnedAt: new Date().toISOString(),
      startFingerprint: 'forged-provider-start',
